      '</div></div></section>';

    // journey / milestones
    var ms=MILESTONES.map(function(m){
      return '<div style="display:flex;flex-direction:column;align-items:center;text-align:center;gap:14px"><div style="font-family:\'Anton\';font-size:clamp(20px,2.2vw,28px);color:var(--ink);letter-spacing:.02em">'+esc(m.year)+'</div><div style="width:22px;height:22px;border-radius:999px;background:var(--gold);border:4px solid var(--bg);box-shadow:0 0 0 2px var(--gold),0 8px 20px -6px rgba(220,156,31,.5);position:relative;z-index:2"></div><div style="font-family:\'Archivo\';font-weight:700;font-size:clamp(12px,1.1vw,14px);line-height:1.35;color:var(--ink);text-wrap:pretty">'+esc(m.label)+'</div><div style="font-family:\'Archivo\';font-size:11.5px;line-height:1.45;color:var(--muted);text-wrap:pretty;max-width:160px">'+esc(m.detail)+'</div></div>';
    }).join('');
